// ============================================================
// Build SerpAPI queries across 7 lead signal types
// D2C-FOCUSED: consumer brands > B2B SaaS
// ============================================================

// Tier 1: D2C / Consumer (high priority — 2 queries each)
const d2cIndustries = [
  'skincare', 'fashion', 'fitness', 'food and beverage',
  'home decor', 'wellness', 'pet care', 'electronics', 'jewelry',
  'supplements', 'baby care', 'organic food', 'athleisure',
  'beauty', 'personal care', 'snacks', 'beverages'
];

// Tier 2: Consumer-facing tech (medium priority — 1 query each)
const consumerTechIndustries = [
  'fintech app', 'edtech app', 'healthtech app', 'gaming app',
  'real estate app', 'food delivery', 'ecommerce'
];

// B2B SaaS intentionally excluded — they don't buy UGC ads

const now = new Date();
const startOfYear = new Date(now.getFullYear(), 0, 0);
const dayOfYear = Math.floor((now - startOfYear) / (1000 * 60 * 60 * 24));
const year = now.getFullYear();

// Rotate: 3 D2C + 2 consumer tech per day
const d2cStart = (dayOfYear * 3) % d2cIndustries.length;
const techStart = (dayOfYear * 2) % consumerTechIndustries.length;
const todayD2C = [];
for (let i = 0; i < 3; i++) todayD2C.push(d2cIndustries[(d2cStart + i) % d2cIndustries.length]);
const todayTech = [];
for (let i = 0; i < 2; i++) todayTech.push(consumerTechIndustries[(techStart + i) % consumerTechIndustries.length]);
const todayIndustries = [...todayD2C, ...todayTech];

const queries = [];

// === SIGNAL 1: Recently Funded D2C Brands ===
queries.push({ query: `D2C brand raised funding India ${year}`, signal: 'funded', industry: 'D2C' });
queries.push({ query: `consumer brand seed series A funding India ${year}`, signal: 'funded', industry: 'D2C' });
queries.push({ query: `Indian D2C startup funding announcement ${year}`, signal: 'funded', industry: 'D2C' });

// === SIGNAL 2: Brands Running Meta/Google Ads ===
queries.push({ query: `D2C brand advertising Instagram Facebook India ${year}`, signal: 'meta_ads', industry: 'general' });
queries.push({ query: `Indian consumer brand scaling performance marketing paid ads`, signal: 'meta_ads', industry: 'general' });

// === SIGNAL 3: Hiring Marketing/Content Roles ===
queries.push({ query: `D2C brand hiring content marketing manager India`, signal: 'hiring', industry: 'general' });
queries.push({ query: `"hiring" "growth marketing" D2C consumer brand India ${year}`, signal: 'hiring', industry: 'general' });

// === SIGNAL 4: Shark Tank / Business Reality Shows ===
queries.push({ query: `Shark Tank India brand ${year}`, signal: 'shark_tank', industry: 'general' });
queries.push({ query: `Shark Tank India new products consumer brand`, signal: 'shark_tank', industry: 'general' });

// === SIGNAL 5: Marketplace to D2C Transition ===
queries.push({ query: `brand launching own website D2C India ${year}`, signal: 'marketplace_to_d2c', industry: 'general' });

// === SIGNAL 6: Creator/Influencer Collaborations ===
queries.push({ query: `brand influencer collaboration India ${year} UGC`, signal: 'creator_collab', industry: 'general' });

// === SIGNAL 7: Industry-Specific Discovery (D2C focus) ===
for (const industry of todayD2C) {
  queries.push({ query: `best ${industry} brands India ${year} D2C`, signal: 'industry_discovery', industry });
  queries.push({ query: `new ${industry} startup India growing direct to consumer`, signal: 'industry_discovery', industry });
}
for (const industry of todayTech) {
  queries.push({ query: `${industry} India ${year} consumer growth`, signal: 'industry_discovery', industry });
}

const signalCounts = {};
for (const q of queries) {
  signalCounts[q.signal] = (signalCounts[q.signal] || 0) + 1;
}

return [{ json: { queries, industries: todayIndustries, signalCounts, totalQueries: queries.length, source: 'schedule' } }];

// ============================================================
// Search SerpAPI — collects both brand sites AND news articles
// News articles (funding, hiring, shark tank) contain brand names
// that Gemini will extract in the enrichment step
// ============================================================
const input = $input.first().json;
const queries = input.queries || [];
const SERP_API_KEY = 'b183c082b67f0971673dbab7ce0a14883f75e5012d09720d17c540efce67bc39';

// Helper: extract domain from URL without URL constructor
function getDomain(link) {
  if (!link) return '';
  const match = link.match(/^https?:\/\/(?:www\.)?([^\/?#]+)/i);
  return match ? match[1].toLowerCase() : '';
}

// News/article domains — results from these contain brand MENTIONS
const articleDomains = new Set([
  'inc42.com', 'yourstory.com', 'entrackr.com', 'economictimes.indiatimes.com',
  'livemint.com', 'moneycontrol.com', 'businessinsider.in', 'techcrunch.com',
  'vccircle.com', 'dealstreetasia.com', 'thehindu.com', 'ndtv.com',
  'businesstoday.in', 'financialexpress.com', 'thehindubusinessline.com',
  'forbesindia.com', 'cnbctv18.com'
]);

// Completely useless domains to skip
const skipDomains = new Set([
  'wikipedia.org', 'google.com', 'facebook.com', 'twitter.com', 'x.com',
  'reddit.com', 'quora.com', 'pinterest.com', 'tiktok.com',
  'play.google.com', 'apps.apple.com', 'medium.com',
  'instagram.com', 'linkedin.com', 'amazon.in', 'amazon.com',
  'flipkart.com', 'myntra.com', 'nykaa.com', 'ajio.com',
  'youtube.com', 'crunchbase.com', 'zoominfo.com', 'tracxn.com',
  'wellfound.com', 'glassdoor.co.in', 'naukri.com', 'indeed.com'
]);

const allResults = [];
const seenUrls = new Set();
const signalHits = {};

for (let i = 0; i < queries.length; i++) {
  const q = queries[i];
  try {
    const url = `https://serpapi.com/search.json?engine=google&q=${encodeURIComponent(q.query)}&api_key=${SERP_API_KEY}&gl=in&hl=en&num=10`;
    const response = await this.helpers.httpRequest({ method: 'GET', url, json: true });
    const organicResults = response.organic_results || [];

    signalHits[q.signal] = (signalHits[q.signal] || 0) + organicResults.length;

    for (const result of organicResults) {
      const link = result.link || '';
      const domain = getDomain(link);
      if (!domain) continue;
      if (skipDomains.has(domain)) continue;
      if (seenUrls.has(link)) continue;
      seenUrls.add(link);

      const isArticle = articleDomains.has(domain) || domain.endsWith('.com') && (
        link.includes('/funding') || link.includes('/startup') ||
        link.includes('/news') || link.includes('/article')
      );

      const title = (result.title || '').trim();
      const snippet = (result.snippet || '').substring(0, 400);

      allResults.push({
        title,
        website: link,
        domain,
        snippet,
        industry: q.industry,
        signal: q.signal || 'unknown',
        search_query: q.query,
        is_article: isArticle
      });
    }
  } catch (err) {
    // Continue on individual query failure
  }

  // 1.2-second delay between requests
  if (i < queries.length - 1) {
    await new Promise(resolve => setTimeout(resolve, 1200));
  }
}

// Cap at 50 results
const capped = allResults.slice(0, 50);
const articleCount = capped.filter(r => r.is_article).length;
const directCount = capped.filter(r => !r.is_article).length;

return [{ json: {
  results: capped,
  totalFound: capped.length,
  articleResults: articleCount,
  directResults: directCount,
  queriesRun: queries.length,
  industries: input.industries || [],
  signalCounts: input.signalCounts || {},
  signalHits
} }];

// ============================================================
// Filter search results: remove existing leads (by domain)
// Also merge System Learnings for downstream evaluation prompts
// ============================================================
const searchData = $('SerpAPI Search').first().json;
const existingResponse = $('Fetch Existing Leads').first().json;
const learningsResponse = $('Fetch System Learnings').first().json;

const results = searchData.results || [];
const existingRecords = (existingResponse.records || []).map(r => r.fields || {});

// Parse System Learnings into a usable format
const learnings = [];
try {
  const learningRecords = (learningsResponse.records || []).map(r => r.fields || {});
  for (const lr of learningRecords) {
    if (lr.learning && lr.category) {
      learnings.push({
        category: lr.category,
        learning: lr.learning,
        confidence: lr.confidence || 0,
        source: lr.source || ''
      });
    }
  }
} catch (e) {
  // Learnings fetch failed, continue without them
}

// Build set of existing domains from Airtable
const existingDomains = new Set();
const existingNames = new Set();
for (const rec of existingRecords) {
  if (rec.company_name) existingNames.add(rec.company_name.toLowerCase().trim());
  if (rec.website) {
    const match = rec.website.match(/^https?:\/\/(?:www\.)?([^\/?#]+)/i);
    if (match) existingDomains.add(match[1].toLowerCase());
  }
}

let duplicatesRemoved = 0;
const filtered = [];

for (const r of results) {
  // For articles (news sites), always keep them
  if (r.is_article) {
    filtered.push(r);
    continue;
  }

  // For direct brand websites, check if already in our Leads
  const domain = (r.domain || '').toLowerCase();
  if (domain && existingDomains.has(domain)) { duplicatesRemoved++; continue; }

  // Also check company name fuzzy match
  const titleLower = r.title.toLowerCase();
  let nameMatch = false;
  for (const name of existingNames) {
    if (name.length > 3 && titleLower.includes(name)) { nameMatch = true; break; }
  }
  if (nameMatch) { duplicatesRemoved++; continue; }

  filtered.push(r);
}

return [{ json: {
  searchResults: filtered,
  totalFound: results.length,
  keptResults: filtered.length,
  duplicatesRemoved,
  articleCount: filtered.filter(r => r.is_article).length,
  directCount: filtered.filter(r => !r.is_article).length,
  existingLeadCount: existingRecords.length,
  industries: searchData.industries || [],
  signalCounts: searchData.signalCounts || {},
  signalHits: searchData.signalHits || {},
  systemLearnings: learnings
} }];

// ============================================================
// Build 3-Evaluation Prompt — Ask Gemini for 3 different
// evaluation perspectives on each batch of prospects:
//   A: Revenue potential focus
//   B: Conversion likelihood focus
//   C: Strategic fit focus
// Integrates System Learnings for data-driven scoring
// Anti-generic: requires SPECIFIC evidence for every score
// ============================================================
const data = $input.first().json;
const results = (data.searchResults || []).slice(0, 15);
const learnings = data.systemLearnings || [];

const signalLabels = {
  funded: 'Recently Funded',
  meta_ads: 'Running Meta/Google Ads',
  hiring: 'Hiring Marketing Roles',
  shark_tank: 'Shark Tank / TV Appearance',
  marketplace_to_d2c: 'Marketplace to D2C Transition',
  creator_collab: 'Creator Collaborations',
  industry_discovery: 'Industry Search',
  custom: 'Custom Search'
};

// Format learnings for injection into prompt
let learningsBlock = '';
if (learnings.length > 0) {
  const formatted = learnings.map((l, i) => {
    return `${i + 1}. [${l.category}] (confidence: ${l.confidence}/10): ${l.learning}`;
  }).join('\n');
  learningsBlock = `\n\n## SYSTEM LEARNINGS FROM PAST OUTREACH\nThese are data-driven insights from our past outreach campaigns. Factor these into your evaluations:\n${formatted}\n`;
}

// Build the search results block
const resultList = results.map((r, i) => {
  const sig = signalLabels[r.signal] || r.signal;
  const type = r.is_article ? 'NEWS ARTICLE' : 'COMPANY WEBSITE';
  return `${i + 1}. [${type}] [Signal: ${sig}]\n   Title: ${r.title}\n   URL: ${r.website}\n   Snippet: ${r.snippet}`;
}).join('\n\n');

const systemPrompt = `You are a business development analyst for Cosmisk, a creative agency in India. Cosmisk offers:
- UGC ads (creator-driven video content for paid ads) — OUR CORE OFFERING
- AI-generated ads and mashup ads
- Performance media buying (Meta + Google)
- Ad account audits and creative strategy

**CRITICAL: Cosmisk's sweet spot is D2C / consumer brands.** UGC content works for brands selling PRODUCTS TO CONSUMERS. 
B2B SaaS companies selling enterprise software DO NOT buy UGC ads. They use whitepapers, webinars, LinkedIn ads — not creator content.

**Business Model Classification (MANDATORY for each company):**
You MUST classify each company's business model as one of:
- "d2c" — sells physical/digital products directly to consumers (skincare, fashion, food, fitness, etc.)
- "b2c_app" — consumer-facing app/platform (fintech app, edtech app, food delivery, gaming)
- "marketplace" — connects buyers and sellers (ecommerce marketplace, rental marketplace)
- "b2b_saas" — sells software/services to businesses (CRM, HR tech, dev tools, cybersecurity, logistics)
- "b2b_services" — sells services to businesses (consulting, recruiting, legal)

This classification DIRECTLY affects scoring — see rules below.
${learningsBlock}
You have TWO jobs:

**JOB 1 — Extract company names from news articles:**
Some results are NEWS ARTICLES (from inc42, yourstory, entrackr, techcrunch, etc.). Extract ACTUAL COMPANY NAMES mentioned. Each article may mention 1-5 companies.

**JOB 2 — Produce THREE independent evaluation perspectives for each company:**

For every company you extract, provide THREE separate evaluations:

### EVALUATION A — Revenue Potential
Focus: Company size indicators, ad spend signals, growth rate, funding amount, market category size.
Score 1-10 based on:
- SPECIFIC funding amount or revenue signals found in snippets (+3 if >$1M raised)
- SPECIFIC evidence of paid ad activity (mention of Meta ads, Google ads, performance marketing) (+2)
- Market size of their category (+1 for large TAM categories like skincare, fintech)
- Growth signals (hiring, expansion, new product lines) (+1)
- Base: 2 for any real company

**BUSINESS MODEL MODIFIERS (Eval A):**
- b2b_saas or b2b_services: PENALTY -2 (enterprise companies have internal creative teams, rarely outsource UGC)
- d2c: BONUS +1 (consumer brands need constant creative refresh)
You MUST cite the specific snippet text or signal that justifies each point. "Good fit for UGC" is NOT acceptable.

### EVALUATION B — Conversion Likelihood
Focus: How likely they are to respond to outreach, signals of active need for creative services.
Score 1-10 based on:
- SPECIFIC evidence they are actively seeking marketing help (job postings for creative roles, agency RFPs) (+3)
- Running ads BUT with low-quality creative (you can infer from snippet context) (+2)
- Recently raised funding AND no apparent in-house creative team (+2)
- Shark Tank / high visibility moment (need content fast) (+2)
- Active social media presence but low engagement (+1)
- Base: 2 for any real company
Penalize (-2) companies with NO clear ad spend signal (no mention of ads, marketing budget, or paid channels).
Bonus (+1) for companies actively hiring for marketing/creative roles.
Bonus (+1) for companies with evidence of running Meta ads (Ad Library, Facebook ads mentioned).

**BUSINESS MODEL MODIFIERS (Eval B):**
- b2b_saas: HARD PENALTY -3 (B2B SaaS almost never responds to UGC agency outreach — they use in-house or performance agencies)
- b2b_services: PENALTY -2 (services companies rarely use UGC)
- d2c with active Instagram/Meta presence: BONUS +2 (highest conversion segment)
- marketplace: PENALTY -1 (marketplaces have in-house creative teams)

### EVALUATION C — Strategic Fit
Focus: Industry alignment with Cosmisk strengths, case study potential, long-term value.
Score 1-10 based on:
- Industry match with Cosmisk's proven verticals (D2C skincare, fashion, fitness, food, wellness, beauty) (+3)
- Potential for compelling case study (unique product, strong brand story) (+2)
- Long-term retainer potential (subscription model, recurring product) (+1)
- Multiple Cosmisk services applicable (UGC + media buying + AI ads) (+1)
- Base: 2 for any real company

**BUSINESS MODEL MODIFIERS (Eval C — MOST IMPORTANT):**
- d2c selling consumer products: BONUS +2 (our ideal client)
- b2c_app with consumer marketing needs: BONUS +1
- b2b_saas: HARD PENALTY -4 (NOT our target market — UGC does not work for enterprise software sales)
- b2b_services: PENALTY -3 (services companies don't use creator content)
- marketplace: PENALTY -1 (large marketplaces have in-house teams)

A B2B SaaS company should NEVER score above 5 on Strategic Fit unless it has a clear consumer-facing product component.

**ANTI-GENERIC RULES (CRITICAL):**
- Every score MUST have a specific justification referencing the search result data
- Do NOT use phrases like "good fit", "potential match", or "seems promising" without evidence
- If you cannot find specific evidence for a score component, do NOT award the points
- Companies with ZERO evidence of ad spend or marketing budget get a -2 penalty on Evaluation B

