const userPrompt = `Here are ${results.length} search results from Google India. Extract companies and evaluate them across all 3 perspectives for Cosmisk's creative services:\n\n${resultList}\n\nExtract all companies mentioned, deduplicate, and provide the 3-evaluation JSON.`;

return [{ json: {
  systemPrompt,
  userPrompt,
  rawResults: results,
  allData: data
} }];

// ============================================================
// Parse 3 Evaluations — extract companies with all 3 scores
// Handles truncated JSON with fallback extraction
// ============================================================
const geminiResponse = $input.first().json;
const prevData = $('Build 3-Evaluation Prompt').first().json;

let companies = [];
let parseError = null;

try {
  const text = (geminiResponse.candidates || [])[0]?.content?.parts?.[0]?.text || '';
  if (!text) throw new Error('No text in Gemini response');

  // Strip markdown code fences
  let cleaned = text.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();

  // Try parsing the full response
  try {
    const parsed = JSON.parse(cleaned);
    companies = parsed.companies || parsed;
    if (!Array.isArray(companies)) {
      // Maybe it's wrapped in another key
      const keys = Object.keys(parsed);
      for (const k of keys) {
        if (Array.isArray(parsed[k])) {
          companies = parsed[k];
          break;
        }
      }
    }
  } catch (parseErr) {
    // Try extracting the array
    const arrMatch = cleaned.match(/\[[\s\S]*\]/);
    if (arrMatch) {
      try {
        companies = JSON.parse(arrMatch[0]);
      } catch (e) {
        // Fall through to object extraction
      }
    }

    // JSON may be truncated — salvage complete objects
    if (companies.length === 0) {
      const objectPattern = /\{[^{}]*"company_name"\s*:\s*"[^"]+"[^{}]*\}/g;
      const matches = cleaned.match(objectPattern) || [];
      for (const m of matches) {
        try {
          const obj = JSON.parse(m);
          if (obj.company_name) companies.push(obj);
        } catch (e) { /* skip malformed */ }
      }
      if (companies.length > 0) {
        parseError = 'Truncated JSON salvaged ' + companies.length + ' companies (evaluations may be incomplete)';
      }
    }
  }
} catch (err) {
  parseError = 'Gemini response parsing failed: ' + err.message;
}

// Normalize: ensure every company has all 3 evaluations (even if partial)
for (const c of companies) {
  if (!c.evaluation_a) c.evaluation_a = { score: 3, justification: 'No evaluation data', revenue_signals: [] };
  if (!c.evaluation_b) c.evaluation_b = { score: 3, justification: 'No evaluation data', conversion_signals: [] };
  if (!c.evaluation_c) c.evaluation_c = { score: 3, justification: 'No evaluation data', strategic_signals: [] };
}

return [{ json: {
  companies,
  companyCount: companies.length,
  parseError,
  rawResults: prevData.rawResults || [],
  allData: prevData.allData || {}
} }];

// ============================================================
// Build Consensus Prompt — synthesize 3 evaluation perspectives
// into a final ranked list with composite scores.
// This is better than scoring evaluations because the goal is
// prospect RANKING, not evaluation quality.
// ============================================================
const data = $input.first().json;
const companies = data.companies || [];
const allData = data.allData || {};
const learnings = allData.systemLearnings || [];

if (companies.length === 0) {
  // No companies to rank, pass through empty
  return [{ json: {
    systemPrompt: '',
    userPrompt: '',
    companies: [],
    allData
  } }];
}

// Format learnings reminder for consensus
let learningsReminder = '';
if (learnings.length > 0) {
  const topLearnings = learnings.slice(0, 5).map(l => `- [${l.category}] ${l.learning}`).join('\n');
  learningsReminder = `\n\nREMINDER — Key learnings from past outreach (factor into final ranking):\n${topLearnings}\n`;
}

// Build the companies block with all 3 evaluations
const companiesBlock = companies.map((c, i) => {
  const evalA = c.evaluation_a || {};
  const evalB = c.evaluation_b || {};
  const evalC = c.evaluation_c || {};
  return `### Company ${i + 1}: ${c.company_name}
Website: ${c.website || 'unknown'}
Industry: ${c.industry || 'unknown'}
Business Model: ${c.business_model || 'unknown'}
Signal: ${c.signal || 'unknown'}
Best Service: ${c.best_service || 'ugc_ads'}
Contact: ${c.contact_title || 'Founder'}
Suggested Platform: ${c.suggested_platform || 'instagram_dm'}
Pitch Hook: ${c.pitch_hook || 'N/A'}

**Evaluation A (Revenue Potential): ${evalA.score || 0}/10**
${evalA.justification || 'N/A'}
Revenue signals: ${(evalA.revenue_signals || []).join(', ') || 'none'}

**Evaluation B (Conversion Likelihood): ${evalB.score || 0}/10**
${evalB.justification || 'N/A'}
Conversion signals: ${(evalB.conversion_signals || []).join(', ') || 'none'}

**Evaluation C (Strategic Fit): ${evalC.score || 0}/10**
${evalC.justification || 'N/A'}
Strategic signals: ${(evalC.strategic_signals || []).join(', ') || 'none'}`;
}).join('\n\n---\n\n');

const systemPrompt = `You are a senior business strategist synthesizing multiple evaluation perspectives into a final prospect ranking for Cosmisk, a creative agency.
${learningsReminder}
Your job is to produce a CONSENSUS RANKING that weighs all three perspectives appropriately:
- Revenue Potential (weight: 30%) — can they afford our services?
- Conversion Likelihood (weight: 40%) — will they actually respond and convert? (MOST IMPORTANT)
- Strategic Fit (weight: 30%) — is this the right client for us?

**CONSENSUS RULES:**
1. A company that scores high on Conversion (B) but low on Revenue (A) is STILL valuable if Strategic Fit (C) is decent — small clients convert fast
2. A company that scores high on Revenue (A) but low on Conversion (B) should be PENALIZED — big companies that won't respond waste time
3. If evaluations DISAGREE significantly (>3 point spread), explain why in your synthesis
4. The composite score is NOT a simple average — apply the weights and your judgment
5. Flag any company where the evaluations seem to contradict each other

**BUSINESS MODEL RULES (CRITICAL):**
6. B2B SaaS companies (business_model = "b2b_saas"): MAXIMUM composite score = 5.0. UGC ads do NOT work for enterprise software. These companies use whitepapers, webinars, and LinkedIn — not creator content. No exceptions unless they have a clear consumer product.
7. B2B Services companies (business_model = "b2b_services"): MAXIMUM composite score = 5.5.
8. D2C consumer brands (business_model = "d2c"): These are our IDEAL clients. If they have funding + ad spend signals, they should score 8+.
9. Consumer apps (business_model = "b2c_app"): Can score up to 8 if they actively run consumer acquisition ads.
10. Marketplaces (business_model = "marketplace"): Cap at 7 unless they specifically need UGC for seller/consumer acquisition.

Return a JSON array of ALL companies, ranked by composite_score (highest first):
[
  {
    "company_name": "BrandName",
    "website": "https://...",
    "industry": "specific_industry",
    "business_model": "d2c|b2c_app|marketplace|b2b_saas|b2b_services",
