  if (contact.founder_name && contact.founder_name !== 'null') {
    const role = contact.contact_role || 'Founder';
    rec.fields.contact_name = contact.founder_name + ' (' + role + ')';
    contactsFound++;
  }

  // Update email
  if (contact.email && contact.email !== 'null' && contact.email.includes('@')) {
    rec.fields.email = contact.email.trim();
    emailsFound++;
  }

  // Append contact details to notes
  const extras = [];
  if (contact.linkedin_url && contact.linkedin_url !== 'null') {
    extras.push('LinkedIn: ' + contact.linkedin_url);
    linkedinsFound++;
  }
  if (contact.instagram_handle && contact.instagram_handle !== 'null') {
    extras.push('Instagram: ' + contact.instagram_handle);
  }
  if (contact.phone && contact.phone !== 'null') {
    extras.push('Phone: ' + contact.phone);
  }

  if (extras.length > 0) {
    rec.fields.notes = (rec.fields.notes || '') + '\n--- Contact Info ---\n' + extras.join('\n');
  }
}

// Update batchBody with merged records
result.batchBody = { records: records };

// Append contact extraction summary to Slack message
const contactSummary = ':mag_right: *Contact Extraction:* ' + contactsFound + '/' + records.length + ' founders identified, ' + emailsFound + ' emails found, ' + linkedinsFound + ' LinkedIn profiles';
if (extractionError) {
  result.slackMsg = result.slackMsg + '\n\n' + contactSummary + '\n:warning: ' + extractionError;
} else {
  result.slackMsg = result.slackMsg + '\n\n' + contactSummary;
}

return [{ json: result }];
